-- Repositionner l'auto-incrémentation
-- Pour H2/PostgreSQL pour éviter les conflits d'ID lors de l'insertion de nouveaux éléments
ALTER TABLE crm_user ALTER COLUMN id RESTART WITH 3;
ALTER TABLE prospect ALTER COLUMN id RESTART WITH 4;
ALTER TABLE contact ALTER COLUMN id RESTART WITH 3;
ALTER TABLE interaction ALTER COLUMN id RESTART WITH 5;
